icerik:
string, harfleri, kelimeleri, cümleleri ve alfanümerik metinleri saklamak için kullanılan veri tipidir.
- C# dilinde string değerler MUTLAKA çift tırnak (" ") içinde yazılır.

Örnek:
string sehir = "Giresun";
string mesaj = "Hoş geldiniz!";

1. Yöntem: Tanımla ve Sonra Değer Ver
string musteriAdi;
musteriAdi = "Ahmet Yılmaz";

2. Yöntem: Tek Satırda Tanımla ve Değer Ver (En Yaygın)
string musteriAdi = "Ahmet Yılmaz";

Kalıp: VeriTipi DegiskenAdi = Deger;

Aşağıdaki kod çalıştığında sehir1 kutusunda ne yazar?

string sehir1 = "Trabzon";
string sehir2 = "Ordu";
sehir1 = sehir2;
sehir2 = "Samsun";

Cevap: 'Ordu' yazar! Çünkü 'sehir1 = sehir2' satırında sehir2'nin o anki kopyası (Ordu) sehir1'e aktarılmıştır. Sonradan sehir2'nin değişmesi sehir1'i etkilemez.

private void btnFisKes_Click(object sender, EventArgs e)
{
    // 1. Kutulardaki metinleri değişkenlere al
    string alici = txtMusteri.Text;
    string tel = txtTelefon.Text;
    string sehir = txtSehir.Text;
    string urun = txtUrun.Text;

    // 2. Formatlı kargo metni oluştur (\n ile)
    string kargoMetni = "================================" + "\n" +
                        "     ARAS KARGO SEVKİYAT FİŞİ    " + "\n" +
                        "================================" + "\n" +
                        "Alıcı Adı : " + alici + "\n" +
                        "Telefon   : " + tel + "\n" +
                        "Varış İli : " + sehir + "\n" +
                        "Ürün      : " + urun + "\n" +
                        "================================" + "\n" +
                        "Durum     : Dağıtıma Hazır ✔";

    // 3. Fiş alanına aktar
    txtFis.Text = kargoMetni;
}

